(5688027, 827479, 108525, '<td valign="top">I think you should increase the contrast a bit and use a more shallow DoF to blur the back ground.</td>', 'I think you should increase the contrast a bit and use a more shallow DoF to blur the back ground.', '2009-10-15 02:55:59.000000', NULL, 1),
(5688030, 827463, 108525, '<td valign="top">Great photo!<br/>The lighting on her face does seems a bit off.  Her right arm is brighter than her face, and so my eyes are drawn to it.</td>', 'Great photo!The lighting on her face does seems a bit off.  Her right arm is brighter than her face, and so my eyes are drawn to it.', '2009-10-15 02:59:07.000000', NULL, 1),
(5688034, 826621, 108525, '<td valign="top">I think this was a nice idea, but a bit overdone.  The asthetic is lost in the jumble.</td>', 'I think this was a nice idea, but a bit overdone.  The asthetic is lost in the jumble.', '2009-10-15 03:10:27.000000', NULL, 1),
