(5694611, 827520, 52549, '<td valign="top">When I saw this during voting I immediately thought it looked like an oil painting. Lovely work, Oliver.</td>', 'When I saw this during voting I immediately thought it looked like an oil painting. Lovely work, Oliver.', '2009-10-21 04:20:45.000000', NULL, 0),
(5694616, 827028, 101531, '<td valign="top">Brilliant shot. Congrats</td>', 'Brilliant shot. Congrats', '2009-10-21 04:24:17.000000', NULL, 0),
(5694638, 827567, 28742, '<td valign="top">Congrats on a personal best and an excellent score, Adam.</td>', 'Congrats on a personal best and an excellent score, Adam.', '2009-10-21 04:48:31.000000', NULL, 0),
(5694639, 827519, 28742, '<td valign="top">Robbed! I gave this a 9.</td>', 'Robbed! I gave this a 9.', '2009-10-21 04:49:38.000000', NULL, 0),
(5694665, 827028, 95579, '<td valign="top">Congratulations. Great shot!!</td>', 'Congratulations. Great shot!!', '2009-10-21 05:17:54.000000', NULL, 0),
(5694684, 827206, 110901, '<td valign="top">Thank you all for the wonderful comments! This was one single exposure, shot in the dark using a rig with various torches/glowsticks/leds etc. The lighting in the bridge is bursts of flash fired through each opening.<br/> <br/>Many thanks to everyone that commented, I am over the moon to have been placed 7th with my first entry and look forward to participating more here :)</td>', 'Thank you all for the wonderful comments! This was one single exposure, shot in the dark using a rig with various torches/glowsticks/leds etc. The lighting in the bridge is bursts of flash fired through each opening. Many thanks to everyone that commented, I am over the moon to have been placed 7th with my first entry and look forward to participating more here :)', '2009-10-21 05:29:42.000000', NULL, 0),
(5694698, 827028, 78115, '<td valign="top">Great job, congrats on ribbon.</td>', 'Great job, congrats on ribbon.', '2009-10-21 05:54:31.000000', NULL, 0),
(5694768, 827625, 52549, '<td valign="top">My goodness, you have a VERY good looking neighbour ;-) I like the outtake maybe just a tiny touch more but love the way you are looking into the lamp... both great shots.<br/>As <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=49109" rel="nofollow" target="_blank">eyewave</a>, I also thought this would finish higher. Congrats on top 20.</td>', 'My goodness, you have a VERY good looking neighbour ;-) I like the outtake maybe just a tiny touch more but love the way you are looking into the lamp... both great shots.As  eyewave, I also thought this would finish higher. Congrats on top 20.', '2009-10-21 07:40:20.000000', NULL, 0),
(5694801, 827204, 101495, '<td valign="top">First time I take a picture of lights in the dark and it came out....not so good, but the next time will be better. Fun challenge and i thank all who voted, even the ones that gave me "1" or "2" just inspires me to do better next time.</td>', 'First time I take a picture of lights in the dark and it came out....not so good, but the next time will be better. Fun challenge and i thank all who voted, even the ones that gave me "1" or "2" just inspires me to do better next time.', '2009-10-21 08:12:24.000000', NULL, 0),
(5694809, 827028, 90495, '<td valign="top">Very cool indeed.</td>', 'Very cool indeed.', '2009-10-21 08:21:51.000000', NULL, 0),
